SELECT device_code, CASE WHEN status_bits >= 9 THEN 'LARGE' ELSE 'SMALL' END AS status_bits_tier, COUNT(*) FILTER (WHERE device_code = 'DV-04') AS dv_04_rows, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS duration_min, STDDEV_SAMP(status_bits) AS status_bits_stddev, ROUND(SUM(status_bits) / NULLIF(COUNT(CASE WHEN device_code = 'DV-01' THEN 1 END), 0), 2) AS status_bits_per_dv_01, COUNT(DISTINCT device_code) AS distinct_device_codes, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, GROUPING(device_code) AS grouping_level FROM device_readings GROUP BY ROLLUP (device_code, CASE WHEN status_bits >= 9 THEN 'LARGE' ELSE 'SMALL' END) ORDER BY device_code NULLS FIRST;
